input.command:
cd /tmp/uni
cat > pb.sh <<'EOF'
#!/bin/bash
# pb.sh A B  -> prints html1 body and html2 body
out=$(/workspace/dataset/test14_executable --a "$(printf '\n\n%s' "$1")" --b "$(printf '\n\n%s' "$2")")
rc=$?
[ $rc -ne 0 ] && echo "EXIT=$rc"
printf '%s\n' "$out" | awk '
  BEGIN{st=0}
  st==0 && /^<h2>Section 1<\/h2>$/ {st=1; print "--A--"; next}
  st==1 && /^<h2>Section 2<\/h2>$/ {st=2; print "--B--"; next}
  st==2 && /^<h1 id="table-of-contents">$/ {exit}
  st==2 && /^<h1 id="table-of-contents">/ {exit}
  st>0 {print}
' | sed -e 's/ /·/g' -e 's/\t/»/g' -e 's/$/|/' -e 's/^--A--|$/--A--/' -e 's/^--B--|$/--B--/'
EOF
chmod +x pb.sh
./pb.sh '# 大标题' '`代码` 段落'
echo "###"
./pb.sh '普通段落  
第二行' '中文。  
行二'
